#include <stdio.h>

int main(void) {
    double peso_kg = 6.4;
    bool prioritaria = true;

    if (peso_kg <= 0.0) {
        printf("Peso non valido.\n");
    } else if (peso_kg > 25.0) {
        printf("Pacco fuori misura.\n");
    } else {
        double tariffa_base = 0.0;
        double supplemento = 0.0;

        printf("Peso pacco: %.2f kg\n", peso_kg);
        if (peso_kg <= 2.0) {
            tariffa_base = 5.00;
            printf("Fascia: Leggero\n");
        } else if (peso_kg <= 10.0) {
            tariffa_base = 9.50;
            printf("Fascia: Medio\n");
        } else {
            tariffa_base = 16.00;
            printf("Fascia: Pesante\n");
        }

        if (prioritaria) {
            supplemento = 4.50;
        }

        double totale = tariffa_base + supplemento;
        printf("Tariffa base: %.2f euro\n", tariffa_base);
        printf("Supplemento prioritaria: %.2f euro\n", supplemento);
        printf("Totale spedizione: %.2f euro\n", totale);
    }

    return 0;
}

#include <math.h>
#include <stdio.h>

int main(void) {
    int campioni_a = 0;
    int somma_a = 420;
    if (campioni_a > 0 && somma_a / campioni_a >= 50) {
        printf("Sensore A: media sufficiente (%d)\n", somma_a / campioni_a);
    } else if (campioni_a > 0) {
        printf("Sensore A: media insufficiente (%d)\n", somma_a / campioni_a);
    } else {
        printf("Sensore A: nessun campione disponibile\n");
    }

    int campioni_b = 6;
    int somma_b = 390;
    if (campioni_b > 0 && somma_b / campioni_b >= 50) {
        printf("Sensore B: media sufficiente (%d)\n", somma_b / campioni_b);
    } else if (campioni_b > 0) {
        printf("Sensore B: media insufficiente (%d)\n", somma_b / campioni_b);
    } else {
        printf("Sensore B: nessun campione disponibile\n");
    }

    double a = 1.0;
    double b = -5.0;
    double c = 6.0;
    double delta = b * b - 4.0 * a * c;
    if (fabs(a) > 1e-12 && delta >= 0.0 && sqrt(delta) > 0.0) {
        double radice_delta = sqrt(delta);
        double x1 = (-b - radice_delta) / (2.0 * a);
        double x2 = (-b + radice_delta) / (2.0 * a);
        printf("Equazione: due radici reali distinte (x1 = %.2f, x2 = %.2f)\n", x1, x2);
    } else {
        printf("Equazione: nessuna coppia di radici reali distinte\n");
    }

    double tensione = 0.1 + 0.2;
    double nominale = 0.3;
    if (fabs(tensione - nominale) <= 1e-9) {
        printf("Tensione: entro la tolleranza nominale\n");
    } else {
        printf("Tensione: fuori tolleranza\n");
    }

    return 0;
}

#include <stdio.h>

int main(void) {
    char codice_treno = 'i';
    int distanza_km = 150;
    int livello_servizio = 2;

    double tariffa_km = 0.0;
    bool codice_valido = true;

    switch (codice_treno) {
        case 'R':
        case 'r':
            tariffa_km = 0.12;
            printf("Categoria treno: Regionale\n");
            break;
        case 'I':
        case 'i':
            tariffa_km = 0.18;
            printf("Categoria treno: Intercity\n");
            break;
        case 'A':
        case 'a':
            tariffa_km = 0.26;
            printf("Categoria treno: Alta Velocita\n");
            break;
        default:
            codice_valido = false;
            printf("Codice treno non valido.\n");
            break;
    }

    if (codice_valido) {
        double prezzo_base = distanza_km * tariffa_km;
        printf("Distanza: %d km\n", distanza_km);
        printf("Prezzo base: %.2f euro\n", prezzo_base);
        printf("Servizi inclusi (livello %d):\n", livello_servizio);

        switch (livello_servizio) {
            case 3:
                printf("- Accesso lounge stazione\n");
                [[fallthrough]];
            case 2:
                printf("- Posto riservato con presa elettrica\n");
                [[fallthrough]];
            case 1:
                printf("- Trasporto bagaglio a mano\n");
                break;
            default:
                printf("- Livello servizio non riconosciuto\n");
                break;
        }
    }

    return 0;
}

#include <stdio.h>

int main(void) {
    double salto_1 = 6.45;
    double salto_2 = 6.78;
    double vento_ms = 1.6;
    bool categoria_junior = true;

    const double miglior_salto = (salto_1 >= salto_2) ? salto_1 : salto_2;
    const double peggior_salto = (salto_1 <= salto_2) ? salto_1 : salto_2;
    const double scarto = (salto_1 >= salto_2) ? (salto_1 - salto_2) : (salto_2 - salto_1);
    const double soglia_qualifica = categoria_junior ? 6.50 : 7.10;
    const char esito_vento = (vento_ms <= 2.0) ? 'V' : 'I';
    const int punti_base = (miglior_salto >= soglia_qualifica) ? 100 : 60;
    const int punti_totali = punti_base + (esito_vento == 'V' ? 15 : 0);

    printf("Miglior salto: %.2f m\n", miglior_salto);
    printf("Peggior salto: %.2f m\n", peggior_salto);
    printf("Scarto tra i salti: %.2f m\n", scarto);
    printf("Soglia qualifica: %.2f m\n", soglia_qualifica);
    printf("Codice vento: %c\n", esito_vento);
    printf("Punti base: %d\n", punti_base);
    printf("Punti totali: %d\n", punti_totali);

    if (miglior_salto >= soglia_qualifica) {
        printf("Esito: Qualificato per la finale\n");
    } else {
        printf("Esito: Non qualificato\n");
    }

    return 0;
}
